91	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
92	     * last two digits of the registrationDate year, e.g. {@code 'SMI-0007-M26'}. Returns
93	     * {@code null} when the owner has no customer code or registration date.
94	     */
95	    default String membershipNumber(Owner owner) {
96	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
97	            return null;
98	        }
99	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
100	    }
101	
102	    /**
103	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits
104	     * contained in the owner's customerCode. Returns {@code null} when the owner has no
105	     * customer code.
106	     */
107	    default Integer checkDigit(Owner owner) {
108	        if (owner == null || owner.getCustomerCode() == null) {
109	            return null;
110	        }
111	        String code = owner.getCustomerCode();
112	        int sum = 0;
113	        boolean dbl = true;
114	        for (int i = code.length() - 1; i >= 0; i--) {
115	            char c = code.charAt(i);
116	            if (c < '0' || c > '9') {
117	                continue;
118	            }
119	            int d = c - '0';
120	            if (dbl) {
121	                d *= 2;
122	                if (d > 9) {
123	                    d -= 9;
124	                }
125	            }
126	            sum += d;
127	            dbl = !dbl;
128	        }
129	        return (10 - (sum % 10)) % 10;
130	    }
131	
132	    /**
133	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
134	     */
135	    default String displayName(Owner owner) {
136	        if (owner == null) {
137	            return null;
138	        }
139	        return owner.getLastName() + ", " + owner.getFirstName();
140	    }
141	
142	    /**
143	     * Returns the owner's initials as the upper-cased first letters of firstName and
144	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
145	     */
146	    default String initials(Owner owner) {
147	        if (owner == null) {
148	            return null;
149	        }
150	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
151	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
152	    }
153	
154	    Owner toOwner(OwnerDto ownerDto);
155	
156	    @Mapping(target = "id", ignore = true)
157	    @Mapping(target = "pets", ignore = true)
158	    Owner toOwner(OwnerFieldsDto ownerDto);
159	
160	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
161	
162	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
163	
164	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
165	        OwnerPageDto ownerPageDto = new OwnerPageDto();
166	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
167	        ownerPageDto.setPage(ownerPage.getNumber());
168	        ownerPageDto.setSize(ownerPage.getSize());
169	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
170	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
171	        return ownerPageDto;
172	    }
